for (let row = 1; row <= 3; row++) {
  let line = '';
  for (let col = 1; col <= 4; col++) {
    line += '*';
  }
  console.log(line);
}

let total = 0;
for (let a = 0; a < 4; a++) {
  for (let b = 0; b < 2; b++) {
    total++;
  }
}
console.log(total);

for (let row = 1; row <= 3; row++) {
  let line = '';
  for (let col = 1; col <= row; col++) {
    line += col;
  }
  console.log(line);
}

let pairs = 0;
for (let x = 1; x <= 3; x++) {
  for (let y = 1; y <= 3; y++) {
    if (x !== y) pairs++;
  }
}
console.log(pairs);

